"""Build scripts/third-party-licenses from the pinned upstream sources in the manifest.

The directory is generated, never committed. Every document is downloaded or derived from an
upstream source and must match the SHA-256 recorded in scripts/third-party-license-sources.json;
nothing is written unless everything matches. See scripts/third-party-notices.md.
Exit codes: 0 built/verified, 1 evidence does not match the manifest, 2 invalid input/tool error.
"""
import argparse
import concurrent.futures
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import sys
import tarfile
import tempfile
import urllib.error
import urllib.parse
import urllib.request
import zipfile

MANIFEST = 'scripts/third-party-license-sources.json'
MANUAL = 'scripts/third-party-notices.manual.json'
USER_AGENT = 'third-party-license-evidence-builder/1'
RECIPES = ('copy', 'leading-comment', 'source-notices', 'source-notice-origins', 'normalized-json', 'inline-json',
           'git-blob-comparison')


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def git_blob_sha1(data):
    return hashlib.sha1(b'blob %d\0' % len(data) + data).hexdigest()


def comment_ranges(data):
    """Return (start, end, kind) for every comment, skipping string and character literals.

    kind is 'block' or 'line'. Line comments on consecutive lines form one range, from the first
    comment marker to the end of the last comment line, so indentation between them is retained.
    """
    found = []
    position, size = 0, len(data)
    while position < size:
        if data.startswith(b'"""', position):
            end = data.find(b'"""', position + 3)
            position = size if end < 0 else end + 3
        elif data[position] in b'"\'':
            quote = data[position]
            position += 1
            while position < size and data[position] != quote and data[position] != 0x0A:
                position += 2 if data[position] == 0x5C else 1
            position += 1
        elif data.startswith(b'/*', position):
            end = data.find(b'*/', position + 2)
            end = size if end < 0 else end + 2
            found.append((position, end, 'block'))
            position = end
        elif data.startswith(b'//', position):
            end = data.find(b'\n', position)
            end = size if end < 0 else end
            if end > position and data[end - 1] == 0x0D:
                end -= 1
            previous = found[-1] if found else None
            if previous and previous[2] == 'line' and re.fullmatch(rb'\r?\n[ \t]*', data[previous[1]:position]):
                found[-1] = (previous[0], end, 'line')
            else:
                found.append((position, end, 'line'))
            position = end
        else:
            position += 1
    return found


def leading_comment(data):
    for _, end, _ in comment_ranges(data):
        return data[:end]
    raise ValueError('Source has no comment')


class Sources:
    """Downloads each upstream URL once into the cache directory."""

    def __init__(self, cache):
        self.cache = cache
        cache.mkdir(parents=True, exist_ok=True)

    def path(self, url):
        return self.cache / sha256(url.encode())

    def fetch(self, url):
        target = self.path(url)
        if target.is_file():
            return
        parsed = urllib.parse.urlsplit(url)
        if parsed.scheme not in ('https', 'file'):
            raise ValueError('Unsupported source URL: ' + url)
        headers = {'User-Agent': USER_AGENT}
        token = os.environ.get('GITHUB_TOKEN') or os.environ.get('GH_TOKEN')
        if token and parsed.netloc == 'api.github.com':
            headers['Authorization'] = 'Bearer ' + token
        error = None
        for _ in range(3):
            try:
                with urllib.request.urlopen(urllib.request.Request(url, headers=headers), timeout=120) as response:
                    data = response.read()
                partial = target.with_name(target.name + '.partial')
                partial.write_bytes(data)
                partial.replace(target)
                return
            except urllib.error.HTTPError as failure:
                error = failure
                if failure.code < 500 and failure.code != 429:
                    break
            except OSError as failure:
                error = failure
        raise ValueError(f'Cannot download {url}: {error}')

    def fetch_all(self, urls, jobs):
        with concurrent.futures.ThreadPoolExecutor(max_workers=jobs) as pool:
            for _ in pool.map(self.fetch, sorted(urls)):
                pass

    def read(self, url):
        return self.path(url).read_bytes()


def archive_entries(path, url, wanted):
    """Yield (name, bytes) for the wanted regular files of a JAR/ZIP or gzip tarball, in archive order."""
    if url.endswith(('.jar', '.zip')):
        with zipfile.ZipFile(path) as archive:
            for info in archive.infolist():
                if not info.is_dir() and wanted(info.filename):
                    yield info.filename, archive.read(info)
    elif url.endswith(('.tar.gz', '.tgz')):
        with tarfile.open(path, mode='r:gz') as archive:
            for member in archive:
                if member.isfile() and wanted(member.name):
                    yield member.name, archive.extractfile(member).read()
    else:
        raise ValueError('Unsupported archive type: ' + url)


class Builder:
    def __init__(self, repo, manifest, sources, update):
        self.repo, self.manifest, self.sources, self.update = repo, manifest, sources, update
        self.problems = []
        self.archives = {archive['url']: archive for archive in manifest.get('archives', [])}
        self.profiles = manifest.get('profiles', {})
        self.blocks = {}
        directory = PurePosixPath(manifest['outputDirectory'])
        if directory.is_absolute() or '..' in directory.parts or not directory.parts:
            raise ValueError('Invalid outputDirectory: ' + manifest['outputDirectory'])
        self.directory = directory
        self.documents = manifest['documents']
        seen = set()
        for document in self.documents:
            path = PurePosixPath(document['path'])
            if '..' in path.parts or path.parts[:len(directory.parts)] != directory.parts or path == directory:
                raise ValueError('Document path is outside ' + str(directory) + ': ' + document['path'])
            if document['path'] in seen:
                raise ValueError('Duplicate document path: ' + document['path'])
            seen.add(document['path'])
            if document.get('recipe', 'copy') not in RECIPES:
                raise ValueError('Unknown recipe for ' + document['path'] + ': ' + document['recipe'])
            for url in self.archive_urls(document):
                if url not in self.archives:
                    raise ValueError('Archive is not listed in archives: ' + url)

    def archive_urls(self, document):
        recipe = document.get('recipe', 'copy')
        urls = []
        if '!/' in document['source'] or recipe in ('source-notices', 'source-notice-origins'):
            urls.append(document['source'].split('!/')[0])
        if recipe == 'git-blob-comparison':
            urls.append(document['sourceArchive'])
        return urls

    def urls(self):
        urls = set()
        for document in self.documents:
            if document.get('recipe') != 'inline-json':
                urls.add(document['source'].split('!/')[0])
            urls.update(self.archive_urls(document))
        return urls

    def expect(self, record, key, actual, label):
        """Compare a pinned hash, or replace it when updating."""
        if record.get(key) == actual:
            return
        if self.update:
            record[key] = actual
        else:
            self.problems.append(f'{label}: {key} is {actual}, manifest pins {record.get(key)}')

    def verify_archives(self):
        for url in sorted(self.urls() & set(self.archives)):
            self.expect(self.archives[url], 'sha256', sha256(self.sources.read(url)), url)

    def entries(self, url, wanted):
        return archive_entries(self.sources.path(url), url, wanted)

    def source_bytes(self, document):
        url, _, entry = document['source'].partition('!/')
        if not entry:
            return self.sources.read(url)
        for _, data in self.entries(url, lambda name: name == entry):
            return data
        raise ValueError(f'{url} has no entry {entry}')

    def notice_blocks(self, url, profile_name):
        """Distinct notice-bearing comments of an archive as [(sha256, text, occurrences)]."""
        key = (url, profile_name)
        if key in self.blocks:
            return self.blocks[key]
        profile = self.profiles[profile_name]
        extensions = tuple(profile['extensions'])
        prefixes = tuple(profile.get('pathPrefixes', ()))
        strip = profile.get('stripComponents', 0)
        kinds = profile['comments']
        pattern = re.compile(profile['pattern'].encode(), re.IGNORECASE)

        def wanted(name):
            relative = '/'.join(name.split('/')[strip:])
            return name.endswith(extensions) and (not prefixes or relative.startswith(prefixes))

        blocks = {}
        for name, data in self.entries(url, wanted):
            source_hash = sha256(data)
            for start, end, kind in comment_ranges(data):
                text = data[start:end]
                if kind not in kinds or not pattern.search(text):
                    continue
                first_line = data.count(b'\n', 0, start) + 1
                blocks.setdefault(sha256(text), (text, []))[1].append({
                    'entry': name, 'sourceSha256': source_hash, 'startByte': start, 'endByteExclusive': end,
                    'startLine': first_line, 'endLine': first_line + text.count(b'\n')})
        ordered = sorted(blocks) if profile['order'] == 'sha256' else list(blocks)
        self.blocks[key] = [(digest, *blocks[digest]) for digest in ordered]
        return self.blocks[key]

    def source_notices(self, document):
        blocks = self.notice_blocks(document['source'], document['profile'])
        if not self.profiles[document['profile']]['entryHeaders']:
            return b'\n\n'.join(text for _, text, _ in blocks) + b'\n'
        parts = []
        for _, text, occurrences in blocks:
            origins = ', '.join(f"{o['entry']}#L{o['startLine']}-L{o['endLine']}" for o in occurrences)
            parts.append(b'Source entries: ' + origins.encode() + b'\n' + text + b'\n\n')
        return b''.join(parts)

    def source_notice_origins(self, document):
        url = document['source']
        origins = {'sourceArchive': url, 'archiveSha256': self.archives[url]['sha256']}
        scope = self.profiles[document['profile']].get('scope')
        if scope:
            origins['scope'] = scope
        origins['blocks'] = [{'commentSha256': digest, 'sources': occurrences}
                             for digest, _, occurrences in self.notice_blocks(url, document['profile'])]
        return (json.dumps(origins, indent=2) + '\n').encode()

    def git_blob_comparison(self, document):
        tree = json.loads(self.sources.read(document['source']))
        if tree.get('truncated'):
            raise ValueError('Upstream tree listing is truncated: ' + document['source'])
        upstream = {item['path']: item['sha'] for item in tree['tree'] if item['type'] == 'blob'}
        rules = [(re.compile(pattern), replacement) for pattern, replacement in document['pathMap']]
        matched, unmatched = [], []
        archive = document['sourceArchive']
        for name, data in self.entries(archive, lambda name: name.endswith(document['entrySuffix'])):
            mapped = next((rule.sub(replacement, name, count=1) for rule, replacement in rules if rule.search(name)),
                          name)
            row = [name, git_blob_sha1(data), upstream.get(mapped)]
            (matched if row[1] == row[2] else unmatched).append(row)
        comparison = {'commit': document['commit'], 'matched': matched, 'unmatched': unmatched,
                      'method': document['method'], 'sourceArchive': archive,
                      'sourceArchiveSha256': self.archives[archive]['sha256'], 'upstreamTree': document['source']}
        return (json.dumps(comparison, indent=2) + '\n').encode()

    def produce(self, document):
        recipe = document.get('recipe', 'copy')
        if recipe == 'inline-json':
            return (json.dumps(document['content'], indent=2) + '\n').encode()
        if recipe == 'source-notices':
            return self.source_notices(document)
        if recipe == 'source-notice-origins':
            return self.source_notice_origins(document)
        if recipe == 'git-blob-comparison':
            return self.git_blob_comparison(document)
        data = self.source_bytes(document)
        if 'sourceFileSha256' in document:
            self.expect(document, 'sourceFileSha256', sha256(data), document['path'])
        if 'gitBlobSha1' in document:
            self.expect(document, 'gitBlobSha1', git_blob_sha1(data), document['path'])
        if recipe == 'leading-comment':
            return leading_comment(data) + (b'\n' if document.get('trailingNewline') else b'')
        if recipe == 'normalized-json':
            return json.dumps(json.loads(data)).encode()
        return data

    def build(self):
        self.verify_archives()
        outputs = {}
        for document in self.documents:
            data = self.produce(document)
            self.expect(document, 'sha256', sha256(data), document['path'])
            outputs[document['path']] = data
        return outputs


def existing_files(directory, cache):
    if not directory.is_dir():
        return []
    return [path for path in sorted(directory.rglob('*'))
            if path.is_file() and not (cache and path.resolve().is_relative_to(cache))]


def write_outputs(repo, directory, outputs, cache):
    for relative, data in outputs.items():
        target = repo / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        if not target.is_file() or target.read_bytes() != data:
            target.write_bytes(data)
    expected = {(repo / relative).resolve() for relative in outputs}
    removed = 0
    for path in existing_files(directory, cache):
        if path.resolve() not in expected:
            path.unlink()
            removed += 1
    for path in sorted(directory.rglob('*'), reverse=True):
        if path.is_dir() and not any(path.iterdir()):
            path.rmdir()
    return removed


def check(repo, directory, documents, cache):
    """Verify the existing directory against the manifest without any network access."""
    problems = []
    expected = set()
    for document in documents:
        path = repo / document['path']
        expected.add(path.resolve())
        if not path.is_file():
            problems.append('Missing: ' + document['path'])
        elif sha256(path.read_bytes()) != document['sha256']:
            problems.append('Does not match the manifest: ' + document['path'])
    for path in existing_files(directory, cache):
        if path.resolve() not in expected:
            problems.append('Not in the manifest: ' + path.relative_to(repo).as_posix())
    return problems


def update_manual(path, outputs):
    """Point the notice generator's manual inventory at the rebuilt documents."""
    if not path.is_file():
        return 0
    manual = json.loads(path.read_text(encoding='utf-8'))
    changed = 0
    for component in manual.get('components', []):
        for document in component.get('documents', []):
            data = outputs.get(document['path'])
            if data is not None and document.get('sha256') != sha256(data):
                document['sha256'] = sha256(data)
                changed += 1
                if 'startLine' in document or 'endLine' in document:
                    print('Review the line range of ' + document['path'] + ' in ' + path.name, file=sys.stderr)
    if changed:
        path.write_text(json.dumps(manual, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
    return changed


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('--repo', type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument('--manifest', type=Path, help='Default: <repo>/' + MANIFEST)
    parser.add_argument('--cache-dir', type=Path, help='Keep downloads here; default is a temporary directory')
    parser.add_argument('--jobs', type=int, default=8, help='Parallel downloads')
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument('--check', action='store_true', help='Verify the existing directory offline; download nothing')
    mode.add_argument('--update-hashes', action='store_true',
                      help='After editing sources in the manifest: rebuild, then record the new hashes in the '
                           'manifest and in ' + MANUAL)
    args = parser.parse_args()
    try:
        repo = args.repo.resolve()
        manifest_path = args.manifest or repo / MANIFEST
        manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
        if manifest.get('schemaVersion') != 1:
            raise ValueError('Unsupported manifest schemaVersion: ' + str(manifest.get('schemaVersion')))
        cache = args.cache_dir.resolve() if args.cache_dir else None
        with tempfile.TemporaryDirectory() as temporary:
            builder = Builder(repo, manifest, Sources(cache or Path(temporary)) if not args.check else None,
                              args.update_hashes)
            directory = repo / builder.directory
            if args.check:
                problems = check(repo, directory, builder.documents, cache)
                for problem in problems:
                    print(problem, file=sys.stderr)
                if problems:
                    print('Run scripts/build-third-party-licenses.py to rebuild ' + str(builder.directory),
                          file=sys.stderr)
                    return 1
                print(f'Verified {len(builder.documents)} documents in {builder.directory}.')
                return 0
            builder.sources.fetch_all(builder.urls(), args.jobs)
            outputs = builder.build()
        if builder.problems:
            for problem in builder.problems:
                print(problem, file=sys.stderr)
            print('Nothing was written. Upstream content differs from the manifest; investigate before using '
                  '--update-hashes.', file=sys.stderr)
            return 1
        removed = write_outputs(repo, directory, outputs, cache)
        if args.update_hashes:
            manifest_path.write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
            changed = update_manual(repo / MANUAL, outputs)
            print(f'Recorded hashes in {manifest_path.name}; updated {changed} manual inventory entries.')
        print(f'Built {len(outputs)} documents in {builder.directory}; removed {removed} stale files.')
        return 0
    except (OSError, ValueError, KeyError, json.JSONDecodeError, zipfile.BadZipFile, tarfile.TarError) as error:
        print('Building third-party license evidence failed: ' + str(error), file=sys.stderr)
        return 2


if __name__ == '__main__':
    sys.exit(main())
